import json, sys
data = json.load(sys.stdin)
result = json.loads(data['result'])
experiments = result['data']['experiments']

# Also check for any experiments with MMLU in metrics that have d000 but might not have 'eval' in name
print('='*80)
print('ALL EXPERIMENTS WITH MMLU METRICS (any d000)')
print('='*80)
mmlu_d000 = {}
for k, v in experiments.items():
    if 'd000' in k.lower() and v.get('metrics'):
        metrics = v['metrics']
        has_mmlu = False
        if isinstance(metrics, dict):
            for mk in metrics.keys():
                if 'mmlu' in mk.lower():
                    has_mmlu = True
                    break
        if has_mmlu:
            mmlu_d000[k] = v

print(f'Found {len(mmlu_d000)} d000 experiments with MMLU scores')
# Already printed above, skip duplicates

# Now look for additional model families in d000 evals
print()
print('='*80)
print('D000 EXPERIMENTS BY MODEL FAMILY')
print('='*80)
families = {}
for k in sorted(experiments.keys()):
    if 'd000' in k.lower():
        # try to extract model family
        lower_k = k.lower()
        if 'falcon' in lower_k:
            family = 'falcon3'
        elif 'phi' in lower_k:
            family = 'phi4'
        elif 'qwen' in lower_k:
            family = 'qwen'
        elif 'llama' in lower_k:
            family = 'llama'
        elif '05b' in lower_k or '0.5b' in lower_k:
            family = 'qwen2.5-0.5B (inferred)'
        elif '15b' in lower_k or '1.5b' in lower_k:
            family = 'qwen2.5-1.5B (inferred)'
        elif '3b' in lower_k:
            family = 'qwen2.5-3B (inferred)'
        elif '7b' in lower_k:
            family = '7B model (inferred)'
        else:
            family = 'unknown'
        families.setdefault(family, []).append(k)

for family, exps in sorted(families.items()):
    print(f'\n  {family}: {len(exps)} experiments')
    for e in exps:
        print(f'    - {e}')
"
